/**
 * The object catalog: what `listObjects` and `describeObject` answer, read from the bundled MIB modules and nothing
 * else.
 *
 * NO TRAFFIC. Every answer here comes from `mib-objects.ts` (what an object is, generated by net-snmp's own parser)
 * and `mib-names.ts` (where it is). The cost of that is the one `objects.ts` already states: the catalog shows what
 * the modules define, not what this agent serves, so a listed table may hold no rows on a given device.
 *
 * WHERE THE DECLARATION GOES. A column carries its textual convention as `type` (what a person reads), the syntax that
 * convention is built on as `baseType` (what a reader deciding prefers), and the module's own three facts about it,
 * syntax, MAX-ACCESS and object identifier, as `declaredType`, which is the spelling the column tooltip shows. An index
 * column is primary and never absent, because its value is written into every instance's identifier; any other
 * column may be absent from a row, because an agent need not instantiate every column of every row. A column whose MAX-ACCESS is
 * `not-accessible` or `accessible-for-notify` cannot be read on its own, so it is not offered for projection.
 */
import { QueryError } from "@/lib/db/errors";
import type { ObjectDetail } from "@/lib/db/types";
import type { ColumnSchema } from "@/lib/types";
import { explainUnknown } from "./mib";
import { MIB_NAMES } from "./mib-names";
import { MIB_SCALAR_GROUPS, MIB_TABLES } from "./mib-objects";
import { sortObjects, type SnmpKind, type SnmpObject } from "./objects";

/** One OBJECT-TYPE under an entry or a group, as the module declares it. */
export interface MibObjectType {
  readonly name: string;
  /** The last sub-identifier; the full identifier is the parent's followed by this. */
  readonly subId: number;
  /** The textual convention where there is one, the SMI syntax otherwise. */
  readonly syntax: string;
  /** The SMI syntax a textual convention is built on. Absent when `syntax` already is one. */
  readonly baseSyntax?: string;
  readonly access: string;
  /** `deprecated` or `obsolete`. Absent means current. */
  readonly status?: string;
}

export interface MibTable {
  readonly name: string;
  readonly module: string;
  readonly entry: string;
  /** The INDEX clause, or for an AUGMENTS entry the INDEX of the entry it augments. */
  readonly index: readonly string[];
  readonly augments?: string;
  readonly status?: string;
  readonly columns: readonly MibObjectType[];
}

export interface MibScalarGroup {
  readonly name: string;
  readonly module: string;
  readonly scalars: readonly MibObjectType[];
}

/** The MAX-ACCESS values that name an object a Get cannot read on its own (RFC 2578 section 7.3). */
const UNREADABLE = new Set(["not-accessible", "accessible-for-notify"]);

const oidOf = (name: string): readonly number[] => MIB_NAMES.get(name) as readonly number[];

/** The objects of one kind, in the order an agent walks them. */
export function catalogObjects(kind: SnmpKind): Array<SnmpObject & { readonly status?: string }> {
  const source = kind === "table" ? MIB_TABLES : MIB_SCALAR_GROUPS;
  const objects = source.map((entry) => ({
    kind,
    name: entry.name,
    module: entry.module,
    oid: oidOf(entry.name),
    ...("status" in entry && entry.status !== undefined ? { status: entry.status } : {}),
  }));
  return sortObjects(objects);
}

function column(parent: readonly number[], object: MibObjectType, primary: boolean): ColumnSchema {
  const identifier = [...parent, object.subId].join(".");
  return {
    name: object.name,
    type: object.syntax,
    ...(object.baseSyntax === undefined ? {} : { baseType: object.baseSyntax }),
    declaredType: `${object.syntax}, ${object.access}, ${identifier}`,
    nullable: !primary,
    isPrimary: primary,
    ...(UNREADABLE.has(object.access) ? { projectable: false } : {}),
  };
}

function refuseByKind(name: string, kind: SnmpKind): never {
  if (!MIB_NAMES.has(name)) throw new QueryError(explainUnknown(name));
  if (kind === "table" && MIB_SCALAR_GROUPS.some((group) => group.name === name)) {
    throw new QueryError(`\`${name}\` is a group of scalars, not a table.`);
  }
  if (kind === "scalars" && MIB_TABLES.some((table) => table.name === name)) {
    throw new QueryError(`\`${name}\` is a table, not a group of scalars.`);
  }
  throw new QueryError(`\`${name}\` is not a table or a group of scalars in the bundled modules.`);
}

/** One object's columns and index, from the module's declaration. Refuses a name that is not one of `kind`. */
export function describeCatalogObject(name: string, kind: SnmpKind): ObjectDetail {
  if (kind === "table") {
    const table = MIB_TABLES.find((candidate) => candidate.name === name);
    if (table === undefined) return refuseByKind(name, kind);
    const entry = oidOf(table.entry);
    return {
      path: [name],
      columns: table.columns.map((object) => column(entry, object, table.index.includes(object.name))),
      indexes: [{ name: table.entry, columns: [...table.index], unique: true }],
      foreignKeys: [],
    };
  }
  const group = MIB_SCALAR_GROUPS.find((candidate) => candidate.name === name);
  if (group === undefined) return refuseByKind(name, kind);
  return {
    path: [name],
    columns: group.scalars.map((object) => column(oidOf(group.name), object, false)),
    indexes: [],
    foreignKeys: [],
  };
}
